```yaml
- ansible.builtin.git:
    repo: 'https://github.com/ansible/ansible.git'
    dest: /tmp/checkout
    version: release-0.22
- ansible.builtin.git: {repo: ..., dest: /tmp/checkout, update: no}
- ansible.builtin.git: {repo: ..., dest: /tmp/checkout, refspec: '+refs/pull/*:refs/heads/*'}
- ansible.builtin.git: {repo: ..., dest: /tmp/checkout, archive: /tmp/ansible.zip}
- ansible.builtin.git: {repo: ..., dest: /tmp/checkout, single_branch: yes, version: master}
- ansible.builtin.git: {repo: 'https://github.com/ansible/ansible.git', dest: /tmp/checkout}
  environment:
    GIT_TERMINAL_PROMPT: 0
```
